def check_demo_logic(i, pair):
    inp = pair['input']
    out = pair['output']
    h, w = len(inp), len(inp[0])

    # Find separator
    sep_type, sep_pos = None, None
    for c in range(w):
        col = [inp[r][c] for r in range(h)]
        if all(v == col[0] and v != 0 for v in col):
            sep_type, sep_pos = 'vertical', c
            break
    if sep_type is None:
        for r in range(h):
            row = [inp[r][c] for c in range(w)]
            if all(v == row[0] and v != 0 for v in row):
                sep_type, sep_pos = 'horizontal', r
                break

    left, right = [], []
    if sep_type == 'vertical':
        left = [row[:sep_pos] for row in inp]
        right = [row[sep_pos+1:] for row in inp]
    else:
        left = inp[:sep_pos]
        right = inp[sep_pos+1:]

    # Test both hypotheses:
    # H1: 3 = same, X = different (X = bridge color)
    # H2: 3 = different, X = same (X = common background)

    bridge = sorted(set() for row in left) & (set() for row in right)
    bridge_colors = set()
    for row in left:
        for cell in row:
            if cell != 0:
                bridge_colors.add(cell)
    for row in right:
        for cell in row:
            if cell != 0:
                bridge_colors.add(cell)

    left_nonzero_colors = set()
    right_nonzero_colors = set()
    for row in left:
        for cell in row:
            if cell != 0:
                left_nonzero_colors.add(cell)
    for row in right:
        for cell in row:
            if cell != 0:
                right_nonzero_colors.add(cell)

    bridge = sorted(left_nonzero_colors & right_nonzero_colors)

    print(f"\nDemo {i}: bridge={bridge}")

    # H1: 3 = same, bridge[0] if bridge else 4 = different
    correct_h1 = 0
    for r in range(len(left)):
        for c in range(len(left[0])):
            same = (left[r][c] == right[r][c])
            if same:
                expected = 3
            else:
                expected = bridge[0] if bridge else 4
            if expected == out[r][c]:
                correct_h1 += 1

    # H2: 3 = different, 0 or something = same
    # The "same" color should be the common background color
    all_nonzero = left_nonzero_colors | right_nonzero_colors
    most_common = max(all_nonzero, key=lambda x: (inp.count(x), -x))  # prioritize more frequent in full input

    correct_h2 = 0
    for r in range(len(left)):
        for c in range(len(left[0])):
            same = (left[r][c] == right[r][c])
            if same:
                expected = 0  # always 0 for same
            else:
                expected = 3
            if expected == out[r][c]:
                correct_h2 += 1

    print(f"H1 (3=same, bridge[0]=diff): {correct_h1}/{len(left)*len(left[0])}")
    print(f"H2 (3=diff, 0=same): {correct_h2}/{len(left)*len(left[0])}")

    return correct_h1, correct_h2, bridge

